using System.Diagnostics.Metrics;
using Microsoft.AspNetCore.Diagnostics.HealthChecks;
using Microsoft.Extensions.Diagnostics.HealthChecks;
using OpenTelemetry.Metrics;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;
using Serilog;
using Serilog.Events;

var builder = WebApplication.CreateBuilder(args);

// Serilog：结构化日志，按命名空间过滤
builder.Host.UseSerilog((ctx, lc) => lc
    .MinimumLevel.Information()
    .MinimumLevel.Override("Microsoft", LogEventLevel.Warning)
    .MinimumLevel.Override("System", LogEventLevel.Warning)
    .Enrich.FromLogContext()
    .Enrich.WithProperty("Service", "order-api")
    .WriteTo.Console()
    .WriteTo.Seq("http://localhost:5341"));

// HealthCheck：区分 readiness 和 liveness
builder.Services.AddHealthChecks()
    .AddCheck("self", () => HealthCheckResult.Healthy("进程正常"), tags: ["live"])
    .AddCheck<DatabaseHealthCheck>("db", tags: ["ready"]);

// OpenTelemetry：Logs 由 Serilog 走 OTLP，Traces + Metrics 统一采集
builder.Services.AddOpenTelemetry()
    .ConfigureResource(r => r.AddService("order-api"))
    .WithTracing(t => t
        .AddAspNetCoreInstrumentation()
        .AddHttpClientInstrumentation()
        .AddOtlpExporter())
    .WithMetrics(m => m
        .AddAspNetCoreInstrumentation()
        .AddHttpClientInstrumentation()
        .AddOtlpExporter());

// 自定义 Metrics
var meter = new Meter("order-api", "1.0");
var orderCounter = meter.CreateCounter<long>("orders.created");
builder.Services.AddSingleton(orderCounter);

var app = builder.Build();

app.MapHealthChecks("/health/ready", new HealthCheckOptions
{
    Predicate = c => c.Tags.Contains("ready")
});
app.MapHealthChecks("/health/live", new HealthCheckOptions
{
    Predicate = c => c.Tags.Contains("live")
});

app.MapPost("/orders", (ILogger<Program> logger, Counter<long> counter) =>
{
    using var scope = logger.BeginScope(new Dictionary<string, object>
    {
        ["OrderId"] = Guid.NewGuid(),
        ["Operation"] = "CreateOrder"
    });
    logger.LogInformation("创建订单");
    counter.Add(1);
    return Results.Ok();
});

app.Run();

class DatabaseHealthCheck : IHealthCheck
{
    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context, CancellationToken ct = default)
    {
        try
        {
            // 真实场景：尝试打开数据库连接
            await Task.Delay(10, ct);
            return HealthCheckResult.Healthy("数据库连接正常");
        }
        catch (Exception ex)
        {
            return HealthCheckResult.Unhealthy("数据库连接失败", ex);
        }
    }
}
